using Mbb.Archive.BuildingBlocks.Domain;namespace Mbb.Archive.Modules.Retention.Domain.Rules;
public enum DispositionAction{Review=0,Destroy=1,Transfer=2,KeepPermanent=3}
public sealed class RetentionRule:AggregateRoot<Guid>{private RetentionRule(){}private RetentionRule(Guid id,string code,string name,int months,DispositionAction action,DateTimeOffset createdAt):base(id){if(string.IsNullOrWhiteSpace(code)||string.IsNullOrWhiteSpace(name))throw new DomainRuleViolationException("Retention rule code and name are required.");if(months<0)throw new DomainRuleViolationException("Retention months cannot be negative.");Code=code.Trim();Name=name.Trim();RetentionMonths=months;Action=action;CreatedAt=createdAt;}public string Code{get;private set;}=string.Empty;public string Name{get;private set;}=string.Empty;public int RetentionMonths{get;private set;}public DispositionAction Action{get;private set;}public DateTimeOffset CreatedAt{get;private set;}public static RetentionRule Create(string code,string name,int months,DispositionAction action,DateTimeOffset now)=>new(Guid.CreateVersion7(),code,name,months,action,now);}
